// 🔑 KONFIGURASI MAYAR
const MAYAR_API_TOKEN = 'GANTI_TOKEN_DI_VPS';

// 🏷️ PRODUCT ID per TIER (produk membership Mayar)
// 1 Tahun   → Rp 599.000 → d8927ccd-4323-4500-b4f3-2f0e4f82acd1
// Life-Time → Rp 999.000 → 56284414-f48b-47b9-af79-74d2b0f4b2dd
const TIERS = {
  yearly: {
    productId: 'd8927ccd-4323-4500-b4f3-2f0e4f82acd1',
    amount: 599000,
    label: 'Langganan 1 Tahun'
  },
  lifetime: {
    productId: '56284414-f48b-47b9-af79-74d2b0f4b2dd',
    amount: 999000,
    label: 'Langganan Life-Time'
  }
};

// URL callback & return
const CALLBACK_URL = 'https://n8n.43-133-131-126.sslip.io/webhook/mayar-callback';

// Endpoint Mayar (terverifikasi)
const MAYAR_ENDPOINT = 'https://api.mayar.id/hl/v1/payment/create';

// Data dari checkout page (n8n v2: JSON langsung di $json)
const raw = $input.first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const nama = (body.nama || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const wa = (body.wa || '').toString().trim();
const discord = (body.discord || '').toString().trim();
const tierInput = (body.tier || 'yearly').toString().trim().toLowerCase();

// Validasi minimal
if (!nama || !email || !wa) {
  throw new Error('Data tidak lengkap: nama, email, dan WA wajib diisi');
}

// Pilih tier: 'yearly' | 'lifetime' (fallback: yearly)
const tier = TIERS[tierInput] ? tierInput : 'yearly';
const t = TIERS[tier];

// URL return (ke halaman status di Vercel — bawa tier & harga buat Pixel Purchase)
const RETURN_URL = 'https://xindelabs-workshop.vercel.app/success.html?tier=' + tier + '&harga=' + t.amount;

// Nomor HP Mayar (format 08..., min 10 digit)
const mobile = wa.replace(/[^0-9]/g, '');
if (mobile.length < 10) {
  throw new Error('Nomor WA tidak valid (minimal 10 digit)');
}

// Payload ke Mayar (amount & productId sesuai tier → invoice muncul sesuai pilihan)
const payload = {
  name: nama,
  email: email,
  mobile: mobile,
  productId: t.productId,
  amount: t.amount,
  callbackUrl: CALLBACK_URL,
  returnUrl: RETURN_URL,
  notes: (t.label + ' ' + (discord || '-')).slice(0, 24)
};

return {
  json: {
    endpoint: MAYAR_ENDPOINT,
    authHeader: 'Bearer ' + MAYAR_API_TOKEN,
    payload: payload,
    tier: tier,
    tierLabel: t.label,
    amount: t.amount,
    customer: { nama: nama, email: email, wa: wa, discord: discord }
  }
};

// Response dari Mayar — struktur: { statusCode, messages, data }
const mayarResp = $input.first().json;

// Cek error
if (mayarResp.statusCode && mayarResp.statusCode >= 400) {
  throw new Error('Mayar error: ' + JSON.stringify(mayarResp));
}

const data = mayarResp.data || {};

// Mayar checkout response — field payment URL bisa bervariasi.
// Cek di response asli lo, lalu samakan field-nya di bawah.
// Response Mayar /payment/create: data.link = invoice URL
const paymentUrl = data.link || data.payment_url || data.url || data.checkout_url || data.redirect_url || '';

if (!paymentUrl) {
  // Kalau response belum punya URL (misal butuh step tambahan),
  // log semua data biar kelihatan strukturnya:
  throw new Error('payment_url tidak ditemukan. Response Mayar: ' + JSON.stringify(mayarResp));
}

return {
  json: {
    payment_url: paymentUrl,
    reference: data.reference || data.id || data.payment_ref || '',
    amount: data.amount || 299000
  }
};

// 🗄️ Siapkan data leads (disimpan SEBELUM user bayar — untuk follow-up)
const payment = $input.first().json;
const customer = payment.customer || {};

// cek duplikat sederhana: kalau leads udah ada, jangan dobel
return {
  json: {
    name: customer.nama || payment.nama || '',
    email: customer.email || payment.email || '',
    whatsapp: customer.wa || payment.wa || '',
    discord_id: customer.discord || payment.discord || '',
    status: 'belum',
    source: 'checkout',
    notes: 'invoice: ' + (payment.reference || '') + ' · tier: ' + (payment.tierLabel || ''),
    supabase_url: 'https://qxzvmnbhplgmspdxdbmg.supabase.co',
    supabase_key: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InF4enZtbmJocGxnbXNwZHhkYm1nIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4NjYwNDIyOSwiZXhwIjoyMTAyMTgwMjI5fQ.UBxJl-T16_ggpFoteFf05hfzENpbgf1rB71sawQhl1M'
  }
};
